from datetime import datetime

def max_errors_in_window(log_text, window_sec):
    fmt = '%Y-%m-%d %H:%M:%S'
    ts = []
    for line in log_text.strip().splitlines():
        parts = line.split(' ', 3)
        if len(parts) >= 3 and parts[2] == 'ERROR':
            ts.append(datetime.strptime(parts[0] + ' ' + parts[1], fmt).timestamp())
    ts.sort()
    best = 0
    j = 0
    for i, t in enumerate(ts):
        while ts[j] < t - window_sec:
            j += 1
        best = max(best, i - j + 1)
    return best

def min_remove_parens(s):
    chars = list(s)
    stack = []
    for i, ch in enumerate(chars):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                chars[i] = ''
    for i in stack:
        chars[i] = ''
    return ''.join(chars)

