from math import gcd

def fraction_add(a, b):
    def parse(f):
        p, q = f.split('/')
        return int(p), int(q)
    p1, q1 = parse(a)
    p2, q2 = parse(b)
    num = p1 * q2 + p2 * q1
    den = q1 * q2
    if num == 0:
        return '0/1'
    g = gcd(abs(num), den)
    return f'{num // g}/{den // g}'

